Change(genesis='e30427e699992327267add669c3bc989f6d16525ba6f493121eec7778638e0ce', deps=('656fa7e7b5b3d6b359e5ffe34b4eaaf50294448a3e7f16d58e1561fe7cf3887f',), event=Authored(todo='publicationquery', at=datetime(2026, 11, 22, 3, 10, 24, 187856), actor='bmabsout', kind='todo', created=datetime(2026, 11, 21, 0, 0, 0), body='A publication run does not fail because one query of the upstream cache failed once', spec=Flat(value=0.45), rationale=('When it fails, the box builds the public tree itself, more than an hour', 'of release build beside the app it serves, and the train waits for it.'), category='', waiting_on='', detail="Seen on 2026-11-21: the build job of a publication run listed one new crate's source package as served by neither cache, and the push job then found the upstream cache serves it and refused the whole push, as it is written to (the list was made wrongly). The script that measures counts a query that fails as not served, so one failed request of many hundreds, sixteen at a time, is enough. The box then built the public tree itself in 73 minutes. To do: the measure tells a path the cache does not hold from a query that failed, asks again a few times, and fails the build job by name where it still cannot tell; the push job's refusal of a path the upstream serves stays. Say also what the train does while the box builds: it holds the one worktree for that hour.\n\nState on 2026-11-22: in work.", source=None, subtodos=(), notes=(), note=''))